function validate([grid]) {
  if (grid.length < 1 || grid.length > 200) return 'grid needs 1 to 200 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 200) return 'grid needs 1 to 200 columns.';
  if (grid.some(row => row.length !== n)) return 'Every row of grid must have the same length.';
  let homes = 0;
  for (const row of grid) for (const v of row) {
    if (v !== 0 && v !== 1) return 'Every cell is 0 or 1.';
    homes += v;
  }
  if (homes < 2) return 'The grid needs at least two homes (1s).';
  return null;
}

