function minTotalDistance(grid) {
  // Try every cell as the meeting point and add up everyone's walk.
  const homes = [];
  grid.forEach((line, r) => line.forEach((cell, c) => { if (cell === 1) homes.push([r, c]); }));
  let best = Infinity;
  for (let r = 0; r < grid.length; r++)
    for (let c = 0; c < grid[0].length; c++) {
      let sum = 0;
      for (const [hr, hc] of homes) sum += Math.abs(hr - r) + Math.abs(hc - c);
      best = Math.min(best, sum);
    }
  return best;
}

