function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const m = size === 'large' ? 100 : 1 + pick(5);
  const n = size === 'large' ? 100 : 1 + pick(5);
  // A 1 by 1 grid cannot hold two homes, so keep at least two cells.
  if (m * n < 2) return [[[1, 1]]];
  const chance = 0.1 + rand() * 0.8;
  for (;;) {
    const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < chance ? 1 : 0)));
    if (grid.flat().filter(v => v === 1).length >= 2) return [grid];
  }
}
